import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount, lineVat, applyVoucher } from '../src/invoices.js';

test('createInvoice returns a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);

  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[0].qty, 10);
  assert.equal(r.value.lines[0].unitPrice, 9500);
  assert.equal(r.value.lines[0].vatRate, 21);

  assert.equal(r.value.lines[1].sku, 'DES-HOUR');
  assert.equal(r.value.lines[1].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].qty, 5);
  assert.equal(r.value.lines[1].unitPrice, 8500);
  assert.equal(r.value.lines[1].vatRate, 21);
});

test('createInvoice normalizes customer ID', () => {
  const r = createInvoice({
    customerId: ' c-001 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice with lowercase customer ID', () => {
  const r = createInvoice({
    customerId: 'c-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
});

test('createInvoice with mixed case and spaces', () => {
  const r = createInvoice({
    customerId: '  c-003  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
});

test('createInvoice defaults to NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice with NET14 terms', () => {
